import { PlanEstudio } from './plan-estudio.model';

export class Carrera {
  private codigo: string;
  private anioVigencia: number;
  private nombre: string;
  private plan: PlanEstudio;

  constructor(codigo: string, anioVigencia: number, nombre: string, plan: PlanEstudio) {
    this.codigo = codigo;
    this.anioVigencia = anioVigencia;
    this.nombre = nombre;
    this.plan = plan;
  }

  getCodigo(): string { return this.codigo; }
  getAnioVigencia(): number { return this.anioVigencia; }
  getNombre(): string { return this.nombre; }

  getPlanEstudio(): PlanEstudio {
    return this.plan;
  }

  getTotalMaterias(): number {
    return this.plan.getMaterias().length;
  }
}
